INSERT INTO message_templates(channel,name,subject,body,management_type,purpose,vertical) VALUES
('email','Verificación del negocio · Email','Consulta sobre {{name}}','<p>{{saludo}}</p><p>{{presentacion}}</p><p>Quería confirmar un dato: ¿este es el contacto de {{name}}{{#if city}} en {{city}}{{/if}}?</p><p>Estamos actualizando la información de los negocios turísticos de la zona y queremos que los datos estén al día.</p><p>{{despedida}}</p>',NULL,'verification',NULL),
('whatsapp','Verificación del negocio · WhatsApp',NULL,'<p>{{saludo}} {{presentacion}}</p><p>¿Este es el contacto de {{name}}{{#if city}} en {{city}}{{/if}}?</p><p>Estamos actualizando los datos de los negocios turísticos de la zona.</p>',NULL,'verification',NULL),
('social','Verificación del negocio · Instagram',NULL,'<p>{{saludo}} {{presentacion}}</p><p>¿Este es el contacto de {{name}}{{#if city}} en {{city}}{{/if}}?</p><p>Estamos actualizando los datos de los negocios turísticos de la zona.</p>',NULL,'verification',NULL),
('email','Primer contacto · Verticales principales · Email','Sumar {{name}} a Hospeda','<p>{{saludo}}</p><p>{{presentacion}}</p><p>Me comunico por {{name}}.{{#if city}} Queremos que quien planea una visita encuentre en un solo lugar dónde dormir, dónde comer y qué hacer {{ref_ciudad}}.{{/if}}</p><p>{{etapa_hospeda}}</p><p>{{propuesta_valor}}</p><p><strong>Para probarlo:</strong> {{prueba_gratis}}</p><p>{{#if temporada}}{{temporada}}{{/if}}</p><p>Toda la información está acá: <a href="{{link_presentacion}}">{{link_presentacion}}</a></p><p>{{pregunta_presentacion}}</p><p>{{despedida}}</p>','main','first_contact',NULL),
('whatsapp','Primer contacto · Verticales principales · WhatsApp',NULL,'<p>{{saludo}} {{presentacion}}</p><p>Me comunico por {{name}}. {{etapa_corta}}</p><p>{{propuesta_corta}} {{prueba_corta}}</p><p>{{pregunta_presentacion}}</p>','main','first_contact',NULL),
('social','Primer contacto · Verticales principales · Instagram',NULL,'<p>{{saludo}} {{presentacion}}</p><p>Me comunico por {{name}}. {{etapa_corta}}</p><p>{{propuesta_corta}} {{prueba_corta}}</p><p>{{pregunta_presentacion}}</p>','main','first_contact',NULL),
('email','Primer contacto · Aliados · Email','Programa de aliados de Hospeda','<p>{{saludo}}</p><p>{{presentacion}}</p><p>Me comunico por {{name}}. {{propuesta_aliados}}</p><p>El programa incluye:</p><ul><li>Logo en la portada de Hospeda</li><li>Difusión en nuestras redes y en el newsletter</li><li>Registro de cada aparición</li></ul><p>{{etapa_hospeda}}</p><p>El nivel y los valores se definen en una charla, según cada caso. Más información: <a href="{{link_aliados}}">{{link_aliados}}</a></p><p>{{pregunta_presentacion}}</p><p>{{despedida}}</p>','partner','first_contact',NULL),
('whatsapp','Primer contacto · Aliados · WhatsApp',NULL,'<p>{{saludo}} {{presentacion}}</p><p>Me comunico por {{name}}. {{propuesta_aliados}}</p><p>Incluye logo en la portada y difusión en redes y newsletter.</p><p>{{pregunta_presentacion}}</p>','partner','first_contact',NULL),
('social','Primer contacto · Aliados · Instagram',NULL,'<p>{{saludo}} {{presentacion}}</p><p>Me comunico por {{name}}. {{propuesta_aliados}}</p><p>Incluye logo en la portada y difusión en redes y newsletter.</p><p>{{pregunta_presentacion}}</p>','partner','first_contact',NULL),
('email','Primer contacto · Proveedores · Email','Directorio de proveedores de Hospeda','<p>{{saludo}}</p><p>{{presentacion}}</p><p>Me comunico por {{name}}. {{propuesta_proveedores}}</p><ul><li>Publicar es gratis y no hay comisiones.</li><li>Los anfitriones contactan directo por WhatsApp.</li><li>A cambio, cada proveedor ofrece un beneficio propio a los anfitriones.</li></ul><p>Así funciona: <a href="{{link_proveedores}}">{{link_proveedores}}</a></p><p>{{pregunta_presentacion}}</p><p>{{despedida}}</p>','provider','first_contact',NULL),
('whatsapp','Primer contacto · Proveedores · WhatsApp',NULL,'<p>{{saludo}} {{presentacion}}</p><p>Me comunico por {{name}}. {{propuesta_proveedores}}</p><p>Publicar es gratis y el contacto es directo.</p><p>{{pregunta_presentacion}}</p>','provider','first_contact',NULL),
('social','Primer contacto · Proveedores · Instagram',NULL,'<p>{{saludo}} {{presentacion}}</p><p>Me comunico por {{name}}. {{propuesta_proveedores}}</p><p>Publicar es gratis y el contacto es directo.</p><p>{{pregunta_presentacion}}</p>','provider','first_contact',NULL),
('email','Primer contacto · Editores · Email','Colaboración editorial con Hospeda','<p>{{saludo}}</p><p>{{presentacion}}</p><p>{{propuesta_editores}}</p><ul><li>Es una colaboración voluntaria y sin exclusividad.</li><li>Cada editor tiene su página de autor.</li><li>Difundimos lo publicado en nuestras redes.</li><li>El texto sigue siendo de quien lo escribe.</li></ul><p>Más detalles: <a href="{{link_editores}}">{{link_editores}}</a></p><p>{{pregunta_presentacion}}</p><p>{{despedida}}</p>','editor','first_contact',NULL),
('whatsapp','Primer contacto · Editores · WhatsApp',NULL,'<p>{{saludo}} {{presentacion}}</p><p>{{propuesta_editores}}</p><p>Es voluntario y sin exclusividad.</p><p>{{pregunta_presentacion}}</p>','editor','first_contact',NULL),
('social','Primer contacto · Editores · Instagram',NULL,'<p>{{saludo}} {{presentacion}}</p><p>{{propuesta_editores}}</p><p>Es voluntario y sin exclusividad.</p><p>{{pregunta_presentacion}}</p>','editor','first_contact',NULL),
('email','Envío de la información · Alojamientos · Email','La presentación de Hospeda para {{name}}','<p>{{saludo}}</p><p>¡Buenísimo, gracias! Acá va la presentación para mirarla con tiempo.</p><p>{{cta_registro}} {{prueba_corta}}</p><p>Los planes, para cuando termine la prueba: <a href="{{link_planes}}">{{link_planes}}</a></p><p>{{ofrecer_ayuda}}</p><p>{{despedida}}</p>','main','resume','Alojamientos'),
