('email','Te armamos la ficha · Email','Armamos la ficha de {{name}}','<p>{{saludo}}</p><p>{{oferta_armado}}</p><p>• Fotos (la principal y algunas más)<br>• Una descripción breve<br>• Horarios y datos de contacto<br>• Redes o sitio web, si hay</p><p>Con eso armamos la ficha y la revisamos juntos.</p><p>{{despedida}}</p>',NULL,'operations',NULL),
('whatsapp','Te armamos la ficha · WhatsApp',NULL,'<p>{{oferta_armado}}</p><p>• Fotos (la principal y algunas más)<br>• Una descripción breve<br>• Horarios y datos de contacto<br>• Redes o sitio web, si hay</p><p>Con eso armamos la ficha y la revisamos juntos.</p>',NULL,'operations',NULL),
