('email','Bienvenida · Email','Bienvenida a Hospeda · {{name}}','<p>{{saludo}} {{presentacion_breve}}</p><p>¡Gracias por registrar {{name}} en Hospeda! {{paso_ficha}}</p><p>{{ofrecer_ayuda}} También están las preguntas frecuentes: <a href="{{link_faq}}">{{link_faq}}</a></p><p>{{despedida}}</p>','accompaniment','care',NULL),
('whatsapp','Bienvenida · WhatsApp',NULL,'<p>{{saludo}} {{presentacion_breve}}</p><p>¡Gracias por registrar {{name}} en Hospeda! {{paso_ficha}}</p><p>{{ofrecer_ayuda}} También están las preguntas frecuentes: {{link_faq}}</p><p>{{despedida}}</p>','accompaniment','care',NULL),
('email','Revisión de la ficha · Email','Revisión de la ficha de {{name}}','<p>{{saludo}} {{presentacion_breve}}</p><p>La ficha de {{name}} ya está armada{{#if hospeda_url}}: {{hospeda_url}}{{/if}}.</p><p>Antes de publicarla conviene revisar que los datos y las fotos estén bien.</p><p>Cualquier cambio, lo corregimos enseguida.</p><p>{{despedida}}</p>',NULL,'operations',NULL),
('whatsapp','Revisión de la ficha · WhatsApp',NULL,'<p>{{saludo}} {{presentacion_breve}}</p><p>La ficha de {{name}} ya está armada{{#if hospeda_url}}: {{hospeda_url}}{{/if}}.</p><p>Antes de publicarla conviene darle una mirada. Cualquier cambio, lo corregimos.</p><p>{{despedida}}</p>',NULL,'operations',NULL),
('email','Fin de la prueba · Email','La prueba de {{name}} en Hospeda está por terminar','<p>{{saludo}} {{presentacion_breve}}</p><p>La prueba de 30 días de {{name}} en Hospeda está por terminar. Para que la ficha siga visible hay que elegir un plan desde la cuenta. Los planes están acá: <a href="{{link_planes}}">{{link_planes}}</a></p><p>Si hace falta, ayudamos a elegir el plan que más convenga.</p><p>{{despedida}}</p>','accompaniment','care',NULL),
('whatsapp','Fin de la prueba · WhatsApp',NULL,'<p>{{saludo}} {{presentacion_breve}}</p><p>La prueba de 30 días de {{name}} en Hospeda está por terminar. Para que la ficha siga visible hay que elegir un plan desde la cuenta. Los planes están acá: {{link_planes}}</p><p>Si hace falta, ayudamos a elegir el plan que más convenga.</p><p>{{despedida}}</p>','accompaniment','care',NULL);
